import json
def f(g):
    import collections
    cnt=collections.Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    seen=set(); comps=[]
    for i,r in enumerate(g):
        for j,x in enumerate(r):
            if x!=bg and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or not(0<=a<len(g)) or not(0<=b<len(g[0])) or g[a][b]==bg: continue
                    seen.add((a,b)); comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1): st.append((a+da,b+db))
                comps.append(comp)
    seed=max(comps,key=len)
    rs=[r for r,c in seed]; cs_=[c for r,c in seed]
    r0,r1,c0,c1=min(rs),max(rs),min(cs_),max(cs_)
    seed=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    mr=(len(seed)-1)//2; mc=(len(seed[0])-1)//2
    res=[row[:] for row in g]
    for comp in comps:
        if len(comp)==1 and comp[0] not in seed and g[comp[0][0]][comp[0][1]]!=bg:
            mi,mj=comp[0]
            for ri in range(len(seed)):
                for ci in range(len(seed[0])):
                    rr,cc_=mi+ri-mr,mj+ci-mc
                    if 0<=rr<len(res) and 0<=cc_<len(res[0]):
                        res[rr][cc_]=seed[ri][ci]
    return res
